import type { HTMLAttributes } from "react";

export function Empty({ className = "", ...props }: HTMLAttributes<HTMLDivElement>) { return <div className={`co-flex co-min-h-56 co-flex-col co-items-center co-justify-center co-gap-3 co-rounded-xl co-border co-border-dashed co-border-black/20 co-p-8 co-text-center ${className}`.trim()} {...props} />; }
export function EmptyTitle({ className = "", ...props }: HTMLAttributes<HTMLHeadingElement>) { return <h3 className={`co-font-semibold ${className}`.trim()} {...props} />; }
export function EmptyDescription({ className = "", ...props }: HTMLAttributes<HTMLParagraphElement>) { return <p className={`co-max-w-md co-text-sm co-text-black/60 ${className}`.trim()} {...props} />; }
export function EmptyActions({ className = "", ...props }: HTMLAttributes<HTMLDivElement>) { return <div className={`co-mt-2 co-flex co-gap-2 ${className}`.trim()} {...props} />; }
